KEYS=sorted(D,key=len,reverse=True)
HX={"a":"エー","b":"ビー","c":"シー","d":"ディー","e":"イー","f":"エフ"}
DG="ゼロ イチ ニ サン ヨン ゴ ロク ナナ ハチ キュウ".split()
def grp(g):
    if g.isdigit(): return g if not g.startswith("0") or g=="0" else "".join(DG[int(c)] for c in g)
    return "".join(HX[c.lower()] if c.lower() in HX else DG[int(c)] for c in g)
def v6(m):
    x=m.group(0);parts=x.split("::")
    f=lambda p:"、".join(grp(g) for g in p.split(":") if g)
    return "、コロンコロン、".join(f(p) for p in parts).strip("、")
def auto(t):
    s=t
    s=re.sub(r'(?<![A-Za-z0-9])(?=[0-9A-Fa-f:]*:[0-9A-Fa-f:]*:)[0-9A-Fa-f]{0,4}(?::{1,2}[0-9A-Fa-f]{0,4}){2,}',v6,s)
    for k in KEYS: s=re.sub(r'(?<![A-Za-z])'+re.escape(k)+r'(?![A-Za-z])',D[k],s)
    s=re.sub(r'(\d+)\.(\d+)\.(\d+)\.(\d+)',lambda m:'、'.join(m.groups()),s)
    s=re.sub(r'(\d+)\.(\d+)\.(\d+)',lambda m:'、'.join(m.groups()),s)
    s=re.sub(r'(\d+)\.(\d+)(?![\dWワGMギメ])',lambda m:'、'.join(m.groups()),s)
    s=re.sub(r'/(\d+)',r'スラッシュ\1',s)
    s=re.sub(r'(\d+)\^(\d+)',r'\1の\2乗',s)
    s=re.sub(r'(?<![\d)）])−(?=\d)','マイナス',s)
    s=s.replace('−','引く').replace('＋','足す')
    return s
